import type { Article } from "./types"
import garland from "@/content/articles/how-to-buy-home-garland-tx.json"
import heroes from "@/content/articles/homes-for-heroes-north-texas.json"
import naca from "@/content/articles/naca-homebuying-dallas-fort-worth.json"

/**
 * Canonical committed article dataset.
 *
 * These files are generated by `node scripts/content/build-articles.mjs` and
 * are the exact documents `scripts/sanity/import-articles.mjs` pushes into the
 * Content Lake. They are the migration source of truth and the fallback the
 * application serves when no Sanity project is configured for an environment.
 *
 * This module exists so the three preserved article URLs never depend on
 * credentials being present. Once Sanity is configured, every read goes to the
 * Content Lake and new articles are published from the Studio with no code
 * change here.
 */
export const datasetArticles = [naca, heroes, garland] as unknown as Article[]
